package glitch

import data.glitch_lib

weak_algorithms := {"DES", "3DES", "RC2", "RC4", "MD5", "SHA1", "SHA-1"}
weak_tls_versions := {"SSLv2", "SSLv3", "TLS 1.0", "TLS 1.1", "TLS1.0", "TLS1.1"}
encryption_related_types := {"encryption", "sse", "tls", "ssl", "cipher", "crypto", "kms"}
key_size_attrs := {"key_bit_length", "key_length", "key_size", "rsa_key_size", "ec_key_size", "bit_length"}

is_weak_algorithm(value) {
    value.ir_type == "String"
    upper_val := upper(value.value)
    weak_algorithms[_] == upper_val
}

is_weak_tls_version(value) {
    value.ir_type == "String"
    regex.match("(?i)(SSLv[23]|TLS[_\\s]?1\\.[01])", value.value)
}

has_insufficient_key_size(value) {
    value.ir_type == "Integer"
    value.value < 128
} else {
    value.ir_type == "String"
    num := to_number(value.value)
    num < 128
}

encryption_enabled_without_algorithm(node) {
    attrs := glitch_lib.all_attributes(node)
    encrypted_attr := attrs[_]
    contains(lower(encrypted_attr.name), "encrypted")
    encrypted_attr.value.ir_type == "Boolean"
    encrypted_attr.value.value == true

    not has_algorithm_specified(node)
}

has_algorithm_specified(node) {
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    contains(lower(attr.name), "algorithm")
    attr.value.ir_type == "String"
    count(attr.value.value) > 0
}

is_encryption_related_atomic_unit(node) {
    type_lower := lower(node.type)
    contains(type_lower, encryption_related_types[_])
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    is_encryption_related_atomic_unit(node)

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    is_weak_algorithm(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Use of weak or deprecated encryption algorithm - Avoid using weak cryptographic algorithms like DES, 3DES, RC4, MD5, or SHA1. (CWE-326)"
    }
}

