weak_algorithms := {"DES", "3DES", "RC2", "RC4", "MD5", "SHA1", "SHA-1", "MD5_CRYPT", "MD5CRYPT", "SHA", "MD5"}

weak_cipher_patterns := {"_AES_128_CBC_", "AES_128_CBC", "_AES_256_CBC_", "AES_256_CBC", "DES", "3DES", "RC4", "NULL", "EXPORT", "TLS_RSA_WITH_AES_128_CBC_SHA", "TLS_RSA_WITH_AES_256_CBC_SHA"}

weak_crypto_fields := {"encrypt", "encryption", "algorithm", "cipher_suites", "cipher", "hash", "checksum", "digest", "password"}

weak_tls_versions := {"SSLv2", "SSLv3", "TLS 1.0", "TLS 1.1", "TLS1.0", "TLS1.1"}

# Check if a string contains any weak algorithm
has_weak_algorithm(str) {
    algo := weak_algorithms[_]
    regex.match(sprintf("(?i)%s", [algo]), str)
}

# Check if a string contains any weak cipher pattern
has_weak_cipher(str) {
    pattern := weak_cipher_patterns[_]
    contains(str, pattern)
}

# Check if field name suggests crypto context and value is weak
is_weak_crypto_field(field_name, field_value) {
    crypto_field := weak_crypto_fields[_]
    regex.match(sprintf("(?i)%s", [crypto_field]), field_name)
    has_weak_algorithm(field_value)
}

is_weak_crypto_field(field_name, field_value) {
    crypto_field := weak_crypto_fields[_]
    regex.match(sprintf("(?i)%s", [crypto_field]), field_name)
    has_weak_cipher(field_value)
}

# Traverse any node to find weak crypto in nested structures
find_weak_crypto_in_node(node) {
    node.ir_type == "String"
    has_weak_algorithm(node.value)
}

find_weak_crypto_in_node(node) {
    node.ir_type == "String"
    has_weak_cipher(node.value)
}

find_weak_crypto_in_node(node) {
    node.ir_type == "Hash"
    entry := node.value[_]
    entry.key.ir_type == "String"
    is_weak_crypto_field(entry.key.value, entry.value.value)
}

find_weak_crypto_in_node(node) {
    node.ir_type == "Array"
    elem := node.value[_]
    find_weak_crypto_in_node(elem)
}

find_weak_crypto_in_node(node) {
    walk(node, [_, child])
    child.ir_type == "String"
    has_weak_algorithm(child.value)
}

find_weak_crypto_in_node(node) {
    walk(node, [_, child])
    child.ir_type == "String"
    has_weak_cipher(child.value)
}

# Check variable names that indicate weak crypto usage
check_variable_name_for_weak_crypto(name, value) {
    regex.match("(?i)(password|cipher|encrypt|hash|digest|md5|sha1|sha-1)", name)
    find_weak_crypto_in_node(value)
