package glitch

import data.glitch_lib

weak_algorithms := {"DES", "3DES", "RC2", "RC4", "MD5", "SHA1", "SHA-1", "MD5_CRYPT", "MD5CRYPT", "SHA", "MD5", "CRC32", "ROT13"}

weak_tls_versions := {"SSLv2", "SSLv3", "TLS 1.0", "TLS 1.1", "TLS1.0", "TLS1.1"}

weak_crypto_keywords := {"encrypt", "encryption", "algorithm", "cipher", "hash", "checksum", "digest", "password", "crypto", "tls", "ssl"}

# Check if a string contains any weak algorithm
has_weak_algorithm(str) {
    algo := weak_algorithms[_]
    regex.match(sprintf("(?i)%s", [algo]), str)
}

# Check if a string contains weak TLS version
has_weak_tls(str) {
    version := weak_tls_versions[_]
    regex.match(sprintf("(?i)%s", [version]), str)
}

# Check if field name suggests crypto context
is_crypto_related_field(name) {
    keyword := weak_crypto_keywords[_]
    regex.match(sprintf("(?i)%s", [keyword]), name)
}

is_weak_algorithm_value(value) {
    value.ir_type == "String"
    has_weak_algorithm(value.value)
}

is_weak_algorithm_value(value) {
    value.ir_type == "String"
    has_weak_tls(value.value)
}

# Find weak crypto in string nodes (non-recursive)
check_string_for_weak_crypto(node) {
    node.ir_type == "String"
    has_weak_algorithm(node.value)
}

check_string_for_weak_crypto(node) {
    node.ir_type == "String"
    has_weak_tls(node.value)
}

# Check hash entries
check_hash_for_weak_crypto(node) {
    node.ir_type == "Hash"
    entry := node.value[_]
    entry.key.ir_type == "String"
    is_crypto_related_field(entry.key.value)
    check_any_value_for_weak_crypto(entry.value)
}

# Check array elements
check_array_for_weak_crypto(node) {
    node.ir_type == "Array"
    elem := node.value[_]
    check_any_value_for_weak_crypto(elem)
}

# Check Access operations (like hash lookups)
check_access_for_weak_crypto(node) {
    node.ir_type == "Access"
    node.right.ir_type == "String"
    has_weak_algorithm(node.right.value)
}

check_access_for_weak_crypto(node) {
    node.ir_type == "Access"
    node.right.ir_type == "String"
    has_weak_tls(node.right.value)
}

# Check MethodCall receivers
check_method_call_for_weak_crypto(node) {
    node.ir_type == "MethodCall"
    check_any_value_for_weak_crypto(node.receiver)
}

# Check FunctionCall arguments
check_function_call_for_weak_crypto(node) {
    node.ir_type == "FunctionCall"
    arg := node.args[_]
    check_any_value_for_weak_crypto(arg)
}

# Main dispatcher for non-recursive weak crypto detection
check_any_value_for_weak_crypto(node) {
    check_string_for_weak_crypto(node)
}

check_any_value_for_weak_crypto(node) {
    check_hash_for_weak_crypto(node)
}

check_any_value_for_weak_crypto(node) {
    check_array_for_weak_crypto(node)
}

check_any_value_for_weak_crypto(node) {
    check_access_for_weak_crypto(node)
}

check_any_value_for_weak_crypto(node) {
    check_method_call_for_weak_crypto(node)
}

check_any_value_for_weak_crypto(node) {
    check_function_call_for_weak_crypto(node)
}

# Check variable name patterns indicating weak crypto
has_weak_crypto_variable_name(name) {
    regex.match("(?i)(password|cipher|encrypt|hash|digest|md5|sha1|sha-1)", name)
}

check_variable_for_weak_crypto(name, value) {
    has_weak_crypto_variable_name(name)
    check_any_value_for_weak_crypto(value)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    variables := glitch_lib.all_variables(parent)
    var := variables[_]

    check_variable_for_weak_crypto(var.name, var.value)

