package glitch

import data.glitch_lib

weak_algorithms := {"DES", "3DES", "RC2", "RC4", "MD5", "SHA1", "SHA-1", "SHA", "sha1", "md5", "MD5CRYPT", "MD5_CRYPT", "md5_crypt"}

weak_ciphers := {"AES_128", "AES_128_CBC", "RC4", "DES", "3DES"}

weak_tls_versions := {"SSLv2", "SSLv3", "TLS 1.0", "TLS 1.1", "TLS_1_0", "TLS_1_1", "1.0", "1.1"}

weak_cipher_in_cbc := {"TLS_RSA_WITH_AES_128_CBC_SHA", "TLS_RSA_WITH_AES_256_CBC_SHA", "AES_128_CBC", "AES_256_CBC"}

crypto_value_names := {"encrypt", "encryption", "cipher", "algorithm", "hash", "digest", "checksum", "crypto", "tls_version", "ssl_version", "protocol", "cipher_suites", "cipher_suite", "key_spec", "key_usage", "customer_master_key_spec", "sse_algorithm"}

# Check if string contains weak algorithm
has_weak_algorithm(str) {
    algo := weak_algorithms[_]
    regex.match(sprintf("(?i)%s", [algo]), str)
}

# Check if string contains weak cipher (but not the CBC variants that are in cipher suites)
has_weak_cipher_only(str) {
    cipher := weak_ciphers[_]
    regex.match(sprintf("(?i)%s", [cipher]), str)
    not regex.match(sprintf("(?i)TLS_RSA_WITH_AES_%s_CBC_SHA", [".*"]), str)
}

# Check if string contains weak TLS version
has_weak_tls(str) {
    tls := weak_tls_versions[_]
    regex.match(sprintf("(?i)%s", [tls]), str)
}

# Check if cipher suite contains weak CBC mode
has_weak_cbc_in_cipher_suite(str) {
    weak := weak_cipher_in_cbc[_]
    regex.match(sprintf("(?i)%s", [weak]), str)
}

# Generic check for weak crypto in string value
check_string_for_weak_crypto(str) {
    has_weak_algorithm(str)
} else {
    has_weak_tls(str)
} else {
    has_weak_cipher_only(str)
} else {
    has_weak_cbc_in_cipher_suite(str)
}

# Recursively check any value for weak crypto strings
check_any_value_for_weak_crypto(value) {
    value.ir_type == "String"
    check_string_for_weak_crypto(value.value)
} else {
    value.ir_type == "Hash"
    val := value.value[_]
    check_any_value_for_weak_crypto(val)
} else {
    value.ir_type == "Array"
    elem := value.value[_]
    check_any_value_for_weak_crypto(elem)
} else {
    value.ir_type == "Access"
    check_any_value_for_weak_crypto(value.left)
} else {
    value.ir_type == "Access"
    check_any_value_for_weak_crypto(value.right)
} else {
    value.ir_type == "MethodCall"
    arg := value.args[_]
    check_any_value_for_weak_crypto(arg)
} else {
    value.ir_type == "FunctionCall"
    arg := value.args[_]
    check_any_value_for_weak_crypto(arg)
}

# Check if attribute/variable name suggests crypto usage and value contains weak crypto
is_crypto_value_name(name) {
    keyword := crypto_value_names[_]
    regex.match(sprintf("(?i)%s", [keyword]), name)
}

# Rule 1: Direct attribute with crypto-related name and weak crypto value
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    au := atomic_units[_]
    attrs := glitch_lib.all_attributes(au)
    attr := attrs[_]
    is_crypto_value_name(attr.name)
    check_any_value_for_weak_crypto(attr.value)
    not is_false_positive_access(attr.value)
    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Use of weak or deprecated encryption algorithm - Crypto-related attribute uses weak algorithm. (CWE-326)"
