    var := vars[_]
    is_crypto_value_name(var.name)
    check_any_value_for_weak_crypto(var.value)
    not is_false_positive_access(var.value)
    result := {
        "type": "sec_weak_crypt",
        "element": var,
        "path": parent.path,
        "description": "Use of weak or deprecated encryption algorithm - Variable with crypto-related name uses weak algorithm. (CWE-326)"
    }
}

# Rule 3: Hash key with crypto-related name containing weak crypto value (for Ansible vars_prompt style)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    walk(parent, [path, node])
    node.ir_type == "Hash"
    entry := node.value[_]
    entry.key.ir_type == "String"
    is_crypto_value_name(entry.key.value)
    check_any_value_for_weak_crypto(entry.value)
    result := {
        "type": "sec_weak_crypt",
        "element": entry,
        "path": parent.path,
        "description": "Use of weak or deprecated encryption algorithm - Hash entry with crypto-related key uses weak algorithm. (CWE-326)"
    }
}

# Rule 4: Any string value containing weak algorithm in crypto context (FunctionCall args)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    walk(parent, [path, node])
    node.ir_type == "FunctionCall"
    arg := node.args[_]
    arg.ir_type == "String"
    has_weak_algorithm(arg.value)
    result := {
        "type": "sec_weak_crypt",
        "element": node,
        "path": parent.path,
