        "element": node,
        "path": parent.path,
        "description": "Use of weak or deprecated encryption algorithm - Method call uses weak algorithm. (CWE-326)"
    }
}

# False positive filters
# Exclude Access nodes that are just reading data (not defining crypto parameters)
is_false_positive_access(value) {
    value.ir_type == "Access"
    value.right.ir_type == "String"
    not is_crypto_value_name(value.right.value)
}

# Exclude cases where the value is just a variable reference to non-crypto field
is_false_positive_access(value) {
    value.ir_type == "Access"
    walk(value, [_, n])
    n.ir_type == "String"
    n.value == "password"
    count({v | walk(value, [_, v]); v.ir_type == "String"}) == 1
}

